import json, subprocess, jsonschema

def verify(candidate, schema, repo_dir, judge):
    # Layer 1: structural, deterministic, nearly free
    try:
        obj = json.loads(candidate.output)
        jsonschema.validate(instance=obj, schema=schema)
    except (json.JSONDecodeError, jsonschema.ValidationError) as e:
        return ("fail", "schema", str(e)[:500])

    # Layer 2: executable ground truth, seconds to minutes
    r = subprocess.run(["pytest", "-q"], cwd=repo_dir,
                       capture_output=True, text=True, timeout=600)
    if r.returncode != 0:          # pytest exit code 0 means all passed
        return ("fail", "tests", r.stdout[-2000:])

    # Layer 3: LLM judge for what code cannot check, last and most costly
    verdict = judge(candidate, rubric="Does the change match the request?")
    if verdict != "pass":
        return ("fail", "judge", verdict)
    return ("pass", None, None)
